import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate(
        [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    ) == pytest.approx(1 / 3)
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_and_handles_empty():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_transcript_log_values_and_skipped_lines():
    assert parse_transcript_log(
        ["  # comment", "", "  ", " x1 , 3 , 1 ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,0,extra", "a,nope,1"])
def test_parse_transcript_log_errors_include_input_line(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", line])


def test_dedupe_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range_and_outside_events():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": True},
    ]
    assert monitor_summary({"g": events, "empty": []}, 1) == {
        "rate": 0.667,
        "recent": 1,
        "groups": 1,
    }
    assert monitor_summary({"empty": []}, 1) == {
        "rate": 0.0,
        "recent": 0,
        "groups": 0,
    }


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
        "middle": [{"flagged": True}, {"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "middle"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "middle"]


def test_flag_rate_by_group_is_sorted_and_empty_is_none():
    groups = {"z": [{"flagged": True}], "a": [], "m": [{"flagged": False}]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "m", "z"]
    assert result == {"a": None, "m": 0.0, "z": 1.0}


def test_longest_flag_streak():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, -1, 0]) == 0
